import type { CaptionTrack, NowPlaying, Playback, Stop } from '../types.generated.js'

/**
 * Plays a video or a sound in a part that shows it: through the page's own
 * media element on the web, and through expo-video on iOS and Android, an
 * optional peer loaded the first time a player is made. A phone without the
 * package, and the server, play nothing.
 */
export interface Media<N> {
  /**
   * Starts `node` playing, and gives whether it plays. A platform that refuses
   * to play before the reader has pressed gives `false`.
   */
  readonly play: (node: N) => Promise<boolean>

  /** Pauses `node` where it stands. */
  readonly pause: (node: N) => void

  /**
   * Moves `node` to `seconds` from its start, held between its start and its
   * end.
   */
  readonly seek: (node: N, seconds: number) => void

  /** Mutes `node`, or gives its sound back. */
  readonly mute: (node: N, muted: boolean) => void

  /** Plays `node` at `rate` times its recorded speed. */
  readonly rate: (node: N, rate: number) => void

  /** Where `node` stands now. */
  readonly read: (node: N) => Playback

  /**
   * Calls `changed` with where `node` stands each time it plays, pauses, moves,
   * loads, ends, or fails, until stopped.
   */
  readonly observe: (node: N, changed: (playback: Playback) => void) => Stop

  /**
   * Shows `node` over the whole screen, or puts it back, and gives whether it
   * stands as asked. On a phone it is the platform's own player.
   */
  readonly fullscreen: (node: N, on: boolean) => Promise<boolean>

  /**
   * Floats `node` in a small window over other apps and pages, or brings it
   * back, and gives whether it stands as asked. A platform without picture in
   * picture gives `false`.
   */
  readonly pictureInPicture: (node: N, on: boolean) => Promise<boolean>

  /** The caption tracks `node`'s media carries, in its order. */
  readonly captions: (node: N) => readonly CaptionTrack[]

  /**
   * Shows the caption track `id` names over `node`, or none where it is `null`.
   * The platform draws the cues.
   */
  readonly showCaptions: (node: N, id: string | null) => void

  /**
   * Says what `node` plays to the system's now-playing controls, on a phone's
   * lock screen and in its control center, and in the browser's media controls
   * through its Media Session where it has one, or takes it off them where it
   * is `null`.
   */
  readonly nowPlaying: (node: N, shown: NowPlaying | null) => void
}
